A.beP=new B.e(4,"Does your mom work on Saturday?","","\uc5b4\uba38\ub2c8\ub294 \ud1a0\uc694\uc77c\uc5d0 \uc77c\ud558\uc138\uc694?","Does",A.O8)
A.ba8=new B.e(5,"Do we need an umbrella?","","\uc6b0\ub9ac \uc6b0\uc0b0\uc774 \ud544\uc694\ud574\uc694?","Do",A.O9)
A.dFo=s([A.bfN,A.b7j,A.beP,A.ba8],t.k)
A.cXG=s(["will drink","would drink","drinking"],t.s)
A.beD=new B.e(2,u.gh,"","\ubc24\uc5d0 \ucee4\ud53c\ub97c \ub9c8\uc2dc\uba74 \uc7a0\uc744 \ubabb \uc790\uc694.","drink",A.cXG)
A.dyD=s(["will heat","would heat","heats"],t.s)
A.bs4=new B.e(3,"If you heat ice, it melts.","","\uc5bc\uc74c\uc744 \ub370\uc6b0\uba74 \ub179\uc544\uc694.","heat",A.dyD)
A.cu1=s(["will be sunny","are sunny","be sunny"],t.s)
A.bov=new B.e(4,"If it is sunny, we eat lunch outside.","","\ub0a0\uc528\uac00 \ub9d1\uc73c\uba74 \uc6b0\ub9ac\ub294 \ubc16\uc5d0\uc11c \uc810\uc2ec\uc744 \uba39\uc5b4\uc694.","is sunny",A.cu1)
A.cSZ=s(["When I will feel","When I would feel","When I feeling"],t.s)
A.bfJ=new B.e(5,"When I feel stressed, I go for a walk.","","\uc2a4\ud2b8\ub808\uc2a4\ub97c \ubc1b\uc73c\uba74 \uc0b0\ucc45\uc744 \uac00\uc694.","When I feel",A.cSZ)
